+const playerState={cash:420,rep:0,health:100,weapon:false,ammo:12,car:null,yaw:0,walking:0, outfit:0};player.position.set(0,0,5);
+const interactables=[];function addPoint(x,z,type,label,action){interactables.push({x,z,type,label,action})}
+addPoint(-27,-21,'court','REC CENTER — hoop run',()=>openPanel('minigames'));addPoint(-29,2,'gym','THE GYM — boxing spar',()=>openPanel('minigames'));addPoint(2,30,'job','JOB BOARD — neighborhood gigs',()=>openPanel('jobs'));addPoint(14,17,'shop','STYLE STUDIO — customize',()=>openPanel('customize'));addPoint(-5,12,'car','RED COUPE',()=>toggleCar(cars[0]));addPoint(5,-4,'car','GOLD SEDAN',()=>toggleCar(cars[1]));addPoint(2,31,'car','BLUE HATCHBACK',()=>toggleCar(cars[2]));
