addPoint(2,31,'car','BLUE HATCHBACK',()=>toggleCar(cars[2]));
// People and world activity
function person(x,z,color=0x5d7180){const p=new THREE.Group();scene.add(p);p.position.set(x,0,z);const skin=new THREE.Mesh(new THREE.SphereGeometry(.22,10,8),M.skin);skin.position.y=1.72;p.add(skin);box(p,0,1.15,0,.54,.75,.32,mat(color));box(p,-.13,.43,0,.2,.65,.23,M.black);box(p,.13,.43,0,.2,.65,.23,M.black);return p}const pedestrians=[person(-8,18,0x85563e),person(8,-18,0x627b89),person(-8,-45,0x75604a),person(8,53,0x46584b)];
// Job and contract systems
const jobList=[['Corner store shift','Stock shelves and run the register on the avenue.','$160'],['Harbor courier','Deliver a legal parcel to the waterfront drop.','$220'],['Rec center coach','Help set up open gym and keep the court lively.','$130'],['Food truck hand','Serve the dinner rush on Cross Street.','$185']];
$('#jobCards').innerHTML=jobList.map((j,i)=>`<div class="card"><div class="eyebrow">SHIFT 0${i+1}</div><h3>${j[0]}</h3><p>${j[1]}</p><div class="reward">${j[2]} · REP +1</div><button data-job="${i}">TAKE THE SHIFT ↗</button></div>`).join('');
function closePanels(){ $$('.panel').forEach(p=>p.classList.remove('open'));document.exitPointerLock?.() }
function openPanel(id){closePanels();$('#'+id)?.classList.add('open');}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2500)}
function setCash(n){playerState.cash+=n;$('#cash').textContent='$'+playerState.cash.toLocaleString()}
function setRep(n){playerState.rep+=n;$('#rep').textContent=playerState.rep}
function changeOutfit(){const styles={street:0x293f3a,sport:0x47748a,work:0x78623f,night:0x32304e};torso.material=mat(styles[$('#styleSelect').value]);const selected=Number(document.querySelector('.swatch.active[data-kind="jacket"]')?.dataset.index||0);torso.material=mat(jacketColors[selected]);}
const skinColors=[0xf1c6a2,0xc98e69,0x925c45,0x58372f,0x382a26],jacketColors=[0x243b35,0x4c7180,0x923f35,0x987640,0x3e385b,0xddd4bc];
function swatchRow(target,colors,kind){$(target).innerHTML=colors.map((c,i)=>`<i class="swatch ${i===(kind==='skin'?2:0)?'active':''}" data-kind="${kind}" data-index="${i}" style="background:#${c.toString(16).padStart(6,'0')}"></i>`).join('')}
swatchRow('#skinSwatches',skinColors,'skin');swatchRow('#jacketSwatches',jacketColors,'jacket');
$$('.swatches').forEach(row=>row.addEventListener('click',e=>{const s=e.target.closest('.swatch');if(!s)return;row.querySelectorAll('.swatch').forEach(v=>v.classList.remove('active'));s.classList.add('active');if(s.dataset.kind==='skin'){head.material=mat(skinColors[+s.dataset.index]);arms.forEach(a=>a.material=head.material)}else changeOutfit()}));
$('#styleSelect').onchange=()=>{const colors={street:0x293f3a,sport:0x47748a,work:0x78623f,night:0x32304e};torso.material=mat(colors[$('#styleSelect').value]);};
$('#hairSelect').onchange=()=>{if($('#hairSelect').value==='beanie'){hair.material=mat(0xc14a36);hair.scale.set(1.05,.72,1.05)}else{hair.material=mat(0x221f1c);hair.scale.set(1,1,1)}};
$('#accessorySelect').onchange=()=>{chain.visible=$('#accessorySelect').value==='chain';toast($('#accessorySelect').value==='glasses'?'Shades equipped. Look sharp.':'Accessory updated.')};
$$('[data-close]').forEach(b=>b.onclick=closePanels);$$('[data-open]').forEach(b=>b.onclick=()=>openPanel(b.dataset.open));
document.addEventListener('click',e=>{const j=e.target.closest('[data-job]');if(j){const job=jobList[+j.dataset.job];setCash(parseInt(job[2].slice(1)));setRep(1);toast(`Shift complete: ${job[0]} · ${job[2]} earned`);closePanels()}});
$('#startRun').onclick=()=>{sideRun=true;runTarget.set(0,0,-66);openPanel('');$('#objectiveTag').textContent='SIDE HUSTLE · ACTIVE';$('#objectiveText').innerHTML='Make the drop <em>— follow the green marker</em>';toast('Package secured. Head to the green marker.');closePanels()};
let sideRun=false;const runTarget=new THREE.Vector3();const marker=new THREE.Mesh(new THREE.TorusGeometry(1.15,.12,8,24),new THREE.MeshBasicMaterial({color:0xd8ff58}));marker.rotation.x=Math.PI/2;marker.position.set(0,.35,-66);scene.add(marker);const beacon=new THREE.PointLight(0xd8ff58,2,14);beacon.position.set(0,2,-66);scene.add(beacon);
// Weapon is a brightly colored foam training blaster; clicks tag practice targets only.
function equip(){playerState.weapon=!playerState.weapon;$('#weaponName').textContent=playerState.weapon?'TRAINING BLASTER':'BARE HANDS';$('#ammo').textContent=playerState.weapon?playerState.ammo+' / 12':'∞';toast(playerState.weapon?'Training blaster equipped. Targets only.':'Training blaster stowed.')}
$$('[data-action="weapon"]').forEach(b=>b.onclick=()=>{equip();closePanels()});
// Vehicle entry/exit: steer on street and avoid walking through buildings.
function toggleCar(car){if(playerState.car){playerState.car=null;player.position.copy(carsCurrentPos);toast('You stepped out.');return}if(car){playerState.car=car;car.speed=0;player.position.copy(car.group.position);carsCurrentPos.copy(player.position);toast(`${car.label} · E to exit`);closePanels()}}
let carsCurrentPos=new THREE.Vector3();function nearestCar(){let best=null,d=4;for(const c of cars){const n=player.position.distanceTo(c.group.position);if(n<d){best=c;d=n}}return best}
$$('[data-action="car"]').forEach(b=>b.onclick=()=>{const c=nearestCar()||cars.slice().sort((a,b)=>a.group.position.distanceTo(player.position)-b.group.position.distanceTo(player.position))[0];if(playerState.car)toggleCar();else if(player.position.distanceTo(c.group.position)<4)toggleCar(c);else toast('Walk up to a parked car to take the wheel.');closePanels()});
// Basketball timing challenge and boxing rhythm spar.
let game={active:false,type:'basketball',score:0,round:0,dir:1,pos:0,done:false};
function startGame(type){game={active:true,type,score:0,round:0,dir:1,pos:0,done:false};$('#gameTitle').textContent=type==='basketball'?'Free throw challenge':'Boxing spar';$('#gameLabel').textContent=type==='basketball'?'COURT 01 · TIMING':'RING 02 · COMBO';$('#gamePrompt').textContent=type==='basketball'?'Stop the moving needle in the green zone.':'Hit when the needle crosses the green zone.';$('#gameScore').textContent=type==='basketball'?'0 / 3':'0 / 5';$('#gameAction').textContent=type==='basketball'?'SHOOT':'PUNCH';openPanel('gameplay');game.active=true}
$$('[data-game]').forEach(b=>b.onclick=()=>startGame(b.dataset.game));$('#gameAction').onclick=takeGameAction;
function takeGameAction(){if(!game.active||game.done)return;const sweet=game.type==='basketball'?(game.pos>=.66&&game.pos<=.78):(game.pos>=.44&&game.pos<=.56);if(sweet){game.score++;toast(game.type==='basketball'?'SWISH! Clean bucket.':'CLEAN HIT! Nice combo.')}else toast(game.type==='basketball'?'Off the rim. Try again.':'You missed the rhythm. Reset.');game.round++;$('#gameScore').textContent=`${game.score} / ${game.type==='basketball'?3:5}`;if(game.round>= (game.type==='basketball'?3:5)){game.done=true;game.active=false;if(game.score>=(game.type==='basketball'?2:3)){const reward=game.type==='basketball'?75:90;setCash(reward);setRep(2);$('#gamePrompt').textContent='You got game. Prize claimed!';toast(`Challenge won · $${reward} + 2 REP`)}else $('#gamePrompt').textContent='Good run. Come back and try again.';$('#gameAction').textContent='DONE';$('#gameAction').onclick=()=>{closePanels();$('#gameAction').onclick=takeGameAction};}}
// controls, camera, interaction
const keys={};let yaw=0,pitch=.12,locked=false;document.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.key==='Tab'){e.preventDefault();openPanel('phone')}if(e.key==='Escape'){closePanels()}if(e.key.toLowerCase()==='e')interact();if(e.key===' '){if(game.active)takeGameAction();else if(!playerState.car)player.position.y=.12}if(e.key.toLowerCase()==='h')openPanel('controls')});document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
renderer.domElement.addEventListener('click',()=>{if(!$$('.panel.open').length){if(playerState.weapon){firePractice()}else if(innerWidth>700)renderer.domElement.requestPointerLock?.()}});document.addEventListener('pointerlockchange',()=>locked=document.pointerLockElement===renderer.domElement);document.addEventListener('mousemove',e=>{if(locked){yaw-=e.movementX*.0022;pitch=THREE.MathUtils.clamp(pitch+e.movementY*.0015,-.35,.55)}});
function firePractice(){if(playerState.ammo<=0){toast('Training magazine empty. Visit the gear locker.');return}playerState.ammo--;$('#ammo').textContent=playerState.ammo+' / 12';toast('Practice shot · no damage');const ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(0,0),camera);const hit=ray.intersectObjects(scene.children,true)[0];if(hit&&hit.distance<42){hit.object.material?.emissive?.set(0x559966);setTimeout(()=>hit.object.material?.emissive?.set(0),100)}}
$$('[data-hold]').forEach(b=>{const k=b.dataset.hold;b.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>keys[k]=false))});$$('[data-action="interact"]').forEach(b=>b.onclick=interact);$$('[data-action="jump"]').forEach(b=>b.onclick=()=>player.position.y=.12);
function interact(){if(playerState.car){toggleCar();return}let nearest=null,dist=4;for(const p of interactables){const d=Math.hypot(player.position.x-p.x,player.position.z-p.z);if(d<dist){dist=d;nearest=p}}const car=nearestCar();if(car&&player.position.distanceTo(car.group.position)<3.8){toggleCar(car);return}if(nearest){nearest.action();return}toast('Nothing nearby. Explore the block.')}

